update public.products set tech_specs = '{"specs":{"Size":"1.5 sq. mm","Type":"Flame Retardant Low Smoke Halogen","Net Quantity":"1 N","Product range":"Life Guard (FR-LSH)","Manufactured By":"Havells India Ltd","Country Of Origin":"India"},"source":"havells.com","features":[{"body":"The oxygen index is 30% for FRLSH insulation .i.e. the Havells FRLSH insulation can catch the flame only if oxygen level in atmosphere or air is more than 30% whereas it known fact that in atmosphere oxygen level is 21% only. Higher the index value, greater the non-combustibility.","title":"High Oxygen Index"}],"description":"Discover Havells WHFFFNKA11X5-C flexible cables, designed for superior durability and performance. Ideal for electrical installations. Buy now for high-quality, flexible wiring solutions.","key_features":["Application : Energy Cables for Internal electrification and power Supply to all electrical operated equipments (eg. Fans/Lights/ Aplliances etc).","Type : FRLSH PVC Flexible Cables upto 1.1kV grade as per IS:694"]}'::jsonb where id = 'hav-whfffnbl11x57';
